import React, { useCallback, useState } from 'react';
import {
  ActivityIndicator, Image, StyleSheet, View, Text, ScrollView,
  TouchableOpacity, StatusBar, Platform,
} from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { useNavigation } from '@react-navigation/native';
import { useFocusEffect } from '@react-navigation/native';
import { useColors } from '../context/ThemeContext';
import { getStorageUrl, userApi } from '../../services/api';
import { storage } from '../../services/storage';

const DAY_LABELS = ['L', 'M', 'X', 'J', 'V', 'S', 'D'];

type Stats = { total_workouts: number; total_hours: number; streak: number; points: number };
type WeekDay = { day: string; mins: number };

function computeAchievements(stats: Stats) {
  return [
    { icon: '🏆', label: 'Primer reto',  unlocked: stats.total_workouts >= 1 },
    { icon: '🔥', label: 'Racha 7d',     unlocked: stats.streak >= 7 },
    { icon: '⚡', label: '100 sesiones', unlocked: stats.total_workouts >= 100 },
    { icon: '🥊', label: 'Activo 10',    unlocked: stats.total_workouts >= 10 },
    { icon: '🏅', label: 'Top 10',       unlocked: false },
    { icon: '💪', label: 'Élite',        unlocked: stats.total_workouts >= 50 },
  ];
}

function getRank(workouts: number) {
  if (workouts >= 100) return 'Guerrero Elite';
  if (workouts >= 50)  return 'Campeón';
  if (workouts >= 20)  return 'Guerrero';
  if (workouts >= 10)  return 'Iniciado';
  return 'Novato';
}

function getLevel(workouts: number) {
  return Math.max(1, Math.floor(workouts / 5) + 1);
}

export default function ProfileScreen() {
  const navigation = useNavigation<any>();
  const { C } = useColors();

  const [userName, setUserName]   = useState('Usuario');
  const [avatarUri, setAvatarUri] = useState<string | null>(null);
  const [stats, setStats]         = useState<Stats>({ total_workouts: 0, total_hours: 0, streak: 0, points: 0 });
  const [weekly, setWeekly]       = useState<WeekDay[]>(DAY_LABELS.map(d => ({ day: d, mins: 0 })));
  const [loading, setLoading]     = useState(true);

  const loadProfile = useCallback(async () => {
    const [t, userRaw] = await Promise.all([storage.get('token'), storage.get('user')]);
    if (userRaw) {
      try {
        const u = JSON.parse(userRaw);
        setUserName(u.name ?? 'Usuario');
        setAvatarUri(getStorageUrl(u.avatar));
      } catch (_) {}
    }
    if (t) {
      try {
        const [statsRes, weeklyRes] = await Promise.all([
          userApi.stats(t),
          userApi.weekly(t),
        ]);
        setStats(statsRes.data);
        if (weeklyRes.data.weekly?.length) setWeekly(weeklyRes.data.weekly);
      } catch (_) {}
    }
    setLoading(false);
  }, []);

  useFocusEffect(useCallback(() => {
    setLoading(true);
    loadProfile();
  }, [loadProfile]));

  const maxMins      = Math.max(1, ...weekly.map(d => d.mins));
  const achievements = computeAchievements(stats);
  const level        = getLevel(stats.total_workouts);
  const xpPercent    = Math.min(100, (stats.total_workouts % 5) * 20);
  const rank         = getRank(stats.total_workouts);

  const STATS_CARDS = [
    { label: 'Entrenos', value: String(stats.total_workouts), icon: 'dumbbell',   color: '#FF2E63' },
    { label: 'Horas',    value: String(stats.total_hours),    icon: 'clock-fast', color: '#00D4FF' },
    { label: 'Racha',    value: String(stats.streak),         icon: 'fire',       color: '#FF6B35' },
  ];

  const todayIndex = new Date().getDay() === 0 ? 6 : new Date().getDay() - 1;
  const avgMins = weekly.length ? Math.round(weekly.reduce((s, d) => s + d.mins, 0) / 7) : 0;

  return (
    <View style={[s.root, { backgroundColor: C.bg }]}>
      <StatusBar barStyle={C.statusBar} backgroundColor="transparent" translucent />

      <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={s.scroll}>

        {/* HERO */}
        <LinearGradient colors={[C.mugenPink + '35', C.bg]} style={s.hero}>
          <View style={[s.topBar, { paddingTop: Platform.OS === 'android' ? (StatusBar.currentHeight ?? 0) + 8 : 52 }]}>
            <Text style={[s.screenTitle, { color: C.textPrimary }]}>Mi Perfil</Text>
            <TouchableOpacity onPress={() => navigation.navigate('screens/SettingsScreen')} style={[s.iconBtn, { backgroundColor: C.card, borderColor: C.border }]}>
              <MaterialCommunityIcons name="cog-outline" size={22} color={C.textPrimary} />
            </TouchableOpacity>
          </View>

          <View style={s.avatarSection}>
            <TouchableOpacity onPress={() => navigation.navigate('screens/EditProfileScreen')} activeOpacity={0.85}>
              <View style={s.avatarRing}>
                <LinearGradient colors={[C.mugenPink, C.mugenPinkDark]} style={StyleSheet.absoluteFill} borderRadius={54} />
                {avatarUri ? (
                  <Image source={{ uri: avatarUri }} style={[s.avatarPlaceholder, { borderColor: C.bg }]} />
                ) : (
                  <View style={[s.avatarPlaceholder, { borderColor: C.bg, backgroundColor: C.elevated }]}>
                    <MaterialCommunityIcons name="account" size={44} color={C.mugenPink} />
                  </View>
                )}
              </View>
              <View style={s.editBtn}>
                <MaterialCommunityIcons name="pencil" size={13} color="#FFF" />
              </View>
            </TouchableOpacity>
          </View>

          <Text style={[s.userName, { color: C.textPrimary }]}>{userName}</Text>
          <LinearGradient colors={[C.mugenPink, C.mugenPinkDark]} style={s.rankBadge} start={{ x: 0, y: 0 }} end={{ x: 1, y: 0 }}>
            <MaterialCommunityIcons name="shield-star" size={13} color="#FFF" />
            <Text style={s.rankBadgeText}>{rank} · Nv.{level}</Text>
          </LinearGradient>

          <View style={s.xpSection}>
            <View style={s.xpLabelRow}>
              <Text style={[s.xpLabel, { color: C.textSecondary }]}>XP hacia nivel {level + 1}</Text>
              <Text style={[s.xpPct, { color: C.mugenPink }]}>{xpPercent}%</Text>
            </View>
            <View style={[s.xpBar, { backgroundColor: C.elevated }]}>
              <LinearGradient
                colors={[C.mugenPink, '#FF6B35']}
                start={{ x: 0, y: 0 }} end={{ x: 1, y: 0 }}
                style={[s.xpFill, { width: `${xpPercent}%` }]}
              />
            </View>
          </View>
        </LinearGradient>

        {/* STATS */}
        {loading ? (
          <ActivityIndicator color={C.mugenPink} style={{ marginTop: 24 }} />
        ) : (
          <View style={s.statsRow}>
            {STATS_CARDS.map(st => (
              <View key={st.label} style={[s.statCard, { backgroundColor: C.card, borderColor: C.border }]}>
                <LinearGradient colors={[st.color + '20', st.color + '06']} style={StyleSheet.absoluteFill} borderRadius={20} />
                <MaterialCommunityIcons name={st.icon as any} size={24} color={st.color} />
                <Text style={[s.statVal, { color: st.color }]}>{st.value}</Text>
                <Text style={[s.statLabel, { color: C.textSecondary }]}>{st.label}</Text>
              </View>
            ))}
          </View>
        )}

        {/* CHART */}
        <View style={[s.chartCard, { backgroundColor: C.card, borderColor: C.border }]}>
          <View style={s.chartHeader}>
            <Text style={[s.cardTitle, { color: C.textPrimary }]}>Actividad semanal</Text>
            <Text style={[s.chartAvg, { color: C.textSecondary }]}>Prom: {avgMins} min</Text>
          </View>
          <View style={s.barChart}>
            {weekly.map((item, i) => {
              const h       = Math.max(4, (item.mins / maxMins) * 110);
              const isToday = i === todayIndex;
              return (
                <View key={item.day} style={s.barCol}>
                  <Text style={[s.barMins, { color: C.textMuted }]}>{item.mins > 0 ? item.mins : ''}</Text>
                  <View style={s.barTrack}>
                    {isToday
                      ? <LinearGradient colors={[C.mugenPink, C.mugenPinkDark]} style={[s.bar, { height: h }]} borderRadius={6} />
                      : <View style={[s.bar, { height: h, backgroundColor: item.mins > 0 ? C.elevated : C.border + '55' }]} />
                    }
                  </View>
                  <Text style={[s.barLabel, { color: isToday ? C.mugenPink : C.textSecondary }]}>{item.day}</Text>
                </View>
              );
            })}
          </View>
        </View>

        {/* LOGROS */}
        <View style={s.section}>
          <View style={s.sectionHeader}>
            <Text style={[s.cardTitle, { color: C.textPrimary }]}>Logros</Text>
            <Text style={[s.seeAll, { color: C.mugenPink }]}>
              {achievements.filter(a => a.unlocked).length}/{achievements.length}
            </Text>
          </View>
          <View style={s.grid}>
            {achievements.map(a => (
              <View key={a.label} style={[s.badge, { backgroundColor: C.card, borderColor: a.unlocked ? C.mugenPink + '35' : C.border, opacity: a.unlocked ? 1 : 0.4 }]}>
                {a.unlocked && <LinearGradient colors={[C.mugenPink + '22', C.mugenPink + '06']} style={StyleSheet.absoluteFill} borderRadius={18} />}
                <Text style={s.badgeIcon}>{a.icon}</Text>
                <Text style={[s.badgeLabel, { color: C.textSecondary }]}>{a.label}</Text>
              </View>
            ))}
          </View>
        </View>

        <View style={{ height: 110 }} />
      </ScrollView>
    </View>
  );
}

const s = StyleSheet.create({
  root:          { flex: 1 },
  scroll:        {},
  hero:          { paddingHorizontal: 20, paddingBottom: 24, alignItems: 'center' },
  topBar:        { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', width: '100%', marginBottom: 20 },
  screenTitle:   { fontSize: 24, fontWeight: '900' },
  iconBtn:       { width: 42, height: 42, borderRadius: 14, justifyContent: 'center', alignItems: 'center', borderWidth: 1 },
  avatarSection: { position: 'relative', marginBottom: 16 },
  avatarRing:    { width: 108, height: 108, borderRadius: 54, justifyContent: 'center', alignItems: 'center', overflow: 'hidden' },
  avatarPlaceholder: { width: 96, height: 96, borderRadius: 48, borderWidth: 3, justifyContent: 'center', alignItems: 'center' },
  editBtn:       { position: 'absolute', bottom: 0, right: 0, width: 30, height: 30, borderRadius: 15, backgroundColor: '#FF2E63', justifyContent: 'center', alignItems: 'center' },
  userName:      { fontSize: 26, fontWeight: '900', marginBottom: 10 },
  rankBadge:     { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 14, paddingVertical: 7, borderRadius: 12, gap: 6, marginBottom: 20 },
  rankBadgeText: { color: '#FFF', fontWeight: '800', fontSize: 13 },
  xpSection:     { width: '100%' },
  xpLabelRow:    { flexDirection: 'row', justifyContent: 'space-between', marginBottom: 8 },
  xpLabel:       { fontSize: 12, fontWeight: '600' },
  xpPct:         { fontSize: 12, fontWeight: '800' },
  xpBar:         { height: 8, borderRadius: 4, overflow: 'hidden' },
  xpFill:        { height: '100%', borderRadius: 4 },
  statsRow:      { flexDirection: 'row', paddingHorizontal: 16, marginTop: 20, gap: 10 },
  statCard:      { flex: 1, borderRadius: 20, padding: 14, alignItems: 'center', gap: 5, overflow: 'hidden', borderWidth: 1 },
  statVal:       { fontSize: 22, fontWeight: '900' },
  statLabel:     { fontSize: 11, fontWeight: '700', textTransform: 'uppercase', letterSpacing: 0.4 },
  chartCard:     { marginHorizontal: 16, marginTop: 16, borderRadius: 24, padding: 20, borderWidth: 1 },
  chartHeader:   { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 },
  cardTitle:     { fontSize: 17, fontWeight: '900' },
  chartAvg:      { fontSize: 12, fontWeight: '600' },
  barChart:      { flexDirection: 'row', alignItems: 'flex-end', justifyContent: 'space-between', height: 150 },
  barCol:        { flex: 1, alignItems: 'center', gap: 4 },
  barMins:       { fontSize: 9, fontWeight: '600' },
  barTrack:      { height: 110, justifyContent: 'flex-end' },
  bar:           { width: 20, borderRadius: 6, minHeight: 4 },
  barLabel:      { fontSize: 11, fontWeight: '800' },
  section:       { marginHorizontal: 16, marginTop: 16 },
  sectionHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 },
  seeAll:        { fontSize: 13, fontWeight: '700' },
  grid:          { flexDirection: 'row', flexWrap: 'wrap', gap: 10 },
  badge:         { width: '30.5%', aspectRatio: 1, borderRadius: 18, justifyContent: 'center', alignItems: 'center', borderWidth: 1.5, overflow: 'hidden', gap: 6 },
  badgeIcon:     { fontSize: 28 },
  badgeLabel:    { fontSize: 10, fontWeight: '800', textAlign: 'center' },
});
